#!/usr/bin/env python3
"""Writes BankLab/UI/DrillCatalogData.h from catalog.py + measured.json (reference stroke and make rate per key).
--check: exit 1 if the header on disk differs (CI: the generated file is committed and must be up to date)."""
import json, os, sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import catalog  # noqa: E402

ROOT = os.path.normpath(os.path.join(HERE, "..", ".."))
OUT = os.path.join(ROOT, "BankLab", "UI", "DrillCatalogData.h")
MEASURED = os.path.join(HERE, "measured.json")
KIND = {"goal": "BL_DRILL_GOAL", "kick": "BL_DRILL_KICK", "bank": "BL_DRILL_BANK", "safety": "BL_DRILL_SAFETY"}


def f(x):
    return repr(round(float(x), 14))


def render():
    measured = json.load(open(MEASURED)) if os.path.exists(MEASURED) else {}
    keys = [d["key"] for d in catalog.DRILLS]
    assert len(keys) == len(set(keys)), "duplicate key"
    chapters = [c for c, _ in catalog.CHAPTERS]
    lines = ["/* GENERATED by Tools/drills/gen_catalog.py from Tools/drills/catalog.py + measured.json — do not edit. */",
             "static const BLDrillSpec BLDrillTable[] = {"]
    last = None
    for d in catalog.DRILLS:
        assert d["chapter"] in chapters, d["key"]
        assert last is None or d["chapter"] >= last, "drills must be grouped by chapter in ladder order: " + d["key"]
        last = d["chapter"]
        assert 1 <= len(d["balls"]) <= 6
        balls = ", ".join("{ %d, %s, %s }" % (i, f(x), f(y)) for i, x, y in d["balls"])
        gx, gy, gr = d["goal"] if d["goal"] else (0, 0, 0)
        m = measured.get(d["key"])
        if d["scan"] == 0:
            solve, pct = (d["angle"], 0, 0), d["assumed_pct"]
        elif m:
            solve, pct = (m["angle"], m["speed"], m["top"]), m["percent"]
        else:
            solve, pct = (0, 0, 0), 0   # not measured yet: the test fails until drill_sweep has run
        lines.append('    { "%s", %d, %s, %d, %d, { %s },\n      %s, %s, %s, %s, %d, %d, %s, %s, %s, %s, %s, %s, %d },' % (
            d["key"], d["chapter"], KIND[d["kind"]], d["rails"], len(d["balls"]), balls,
            f(d["angle"]), f(gx), f(gy), f(gr), int(d["pot_required"]), int(d["pot_only"]), f(d["tip"]), f(d["jitter"]),
            f(d["scan"]), f(solve[0]), f(solve[1]), f(solve[2]), pct))
    lines.append("};")
    lines.append("#define BL_DRILL_CHAPTERS %d" % len(catalog.CHAPTERS))
    lines.append("static const char *const BLDrillChapterKeys[BL_DRILL_CHAPTERS] = { %s };" %
                 ", ".join('"%s"' % k for _, k in catalog.CHAPTERS))
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    text = render()
    if "--check" in sys.argv:
        ok = os.path.exists(OUT) and open(OUT).read() == text
        print("DrillCatalogData.h " + ("up to date" if ok else "OUT OF DATE: run Tools/drills/gen_catalog.py"))
        sys.exit(0 if ok else 1)
    open(OUT, "w").write(text)
    print("wrote", os.path.relpath(OUT, ROOT), len(catalog.DRILLS), "drills")
